export type ParsedRepayInstruction<
  TProgram extends string = typeof LEDGERLINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    line: TAccountMetas[1];
    reserveAta: TAccountMetas[2];
    usdcMint: TAccountMetas[3];
    from: TAccountMetas[4];
    /** Either the borrower or the keeper (for an automated dividend repayment). */
    payerAuthority: TAccountMetas[5];
    tokenProgram: TAccountMetas[6];
  };
  data: RepayInstructionData;
};

export function parseRepayInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRepayInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      line: getNextAccount(),
      reserveAta: getNextAccount(),
      usdcMint: getNextAccount(),
      from: getNextAccount(),
      payerAuthority: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getRepayInstructionDataDecoder().decode(instruction.data),
  };
}
